import type { AutocompleteProps } from "@pisagor/react";
import { Autocomplete } from "@pisagor/react";
import { type FieldPresentationProps, FieldShell } from "../../internal/field-shell";

// #region Types
interface AutocompleteOption {
  label: string;
  value: string;
}

export interface AutocompleteFieldProps
  extends FieldPresentationProps,
    Omit<AutocompleteProps, "invalid" | "name" | "onValueChange" | "value"> {
  name?: string;
  value?: string;
  items: Array<AutocompleteOption | string>;
  onBlur?: () => void;
  onValueChange?: (value: string) => void;
}
// #endregion

// #region Component
export function AutocompleteField({
  orientation,
  invalid,
  items,
  name,
  value,
  description,
  error,
  id,
  label,
  labelAccessory,
  labelProps,
  onBlur,
  onValueChange,
  className,
  ...autocompleteProps
}: AutocompleteFieldProps) {
  return (
    <FieldShell
      className={className}
      description={description}
      error={error}
      id={id}
      invalid={invalid}
      label={label}
      labelAccessory={labelAccessory}
      labelProps={labelProps}
      orientation={orientation}
    >
      <Autocomplete
        {...autocompleteProps}
        {...(value !== undefined ? { value: value ? [value] : [] } : {})}
        id={id}
        invalid={invalid}
        items={items}
        name={name}
        onFocusOutside={onBlur}
        onValueChange={(nextValue) => onValueChange?.(nextValue.at(0) ?? "")}
      />
    </FieldShell>
  );
}
// #endregion

import type { CheckboxProps } from "@pisagor/react";
import { Checkbox, Field } from "@pisagor/react";
import type { FieldPresentationProps } from "../../internal/field-shell";

// #region Types
export interface CheckboxFieldProps
  extends FieldPresentationProps,
    Omit<CheckboxProps, "checked" | "invalid" | "name" | "onCheckedChange" | "onValueChange"> {
  orientation?: "horizontal" | "vertical" | "responsive";
  checked?: boolean;
  name?: string;
  onBlur?: () => void;
  onValueChange?: (checked: boolean) => void;
}
// #endregion

// #region Component
export function CheckboxField({
  orientation = "horizontal",
  checked,
  invalid,
  name,
  description,
  error,
  id,
  label,
  labelAccessory,
  labelProps,
  onBlur,
  onValueChange,
  className,
  ...checkboxProps
}: CheckboxFieldProps) {
  const hasLabel = Boolean(label ?? labelAccessory);

  return (
    <Field className={className} invalid={invalid} orientation={orientation}>
      <Checkbox
        {...checkboxProps}
        {...(checked !== undefined ? { checked } : {})}
        id={id}
        invalid={invalid}
        name={name}
        onBlur={onBlur}
        onValueChange={onValueChange}
      />
      {hasLabel || description ? (
        <Field.Content>
          {hasLabel ? (
            <Field.Label {...labelProps} htmlFor={id}>
              {label}
              {labelAccessory}
            </Field.Label>
          ) : null}
          {description ? <Field.Description>{description}</Field.Description> : null}
        </Field.Content>
      ) : null}
      {error ? <Field.Error>{error}</Field.Error> : null}
    </Field>
  );
}
