      description={description}
      error={error}
      id={id}
      invalid={invalid}
      label={label}
      labelAccessory={labelAccessory}
      labelProps={labelProps}
      orientation={orientation}
    >
      <Textarea
        {...textareaProps}
        {...(value !== undefined ? { value } : {})}
        id={id}
        name={name}
        onBlur={onBlur}
        onChange={(event) => onValueChange?.(event.target.value)}
      />
    </FieldShell>
  );
}
